   function onDropFromLibrary(e: DragEvent, dropPosition: LayoutItem) {
     const payload = JSON.parse(e.dataTransfer.getData('application/x-spm-widget'));
     if (payload.mode === 'parameter') {
       // Open popup
       setPendingDrop({ parameterId: payload.parameterId, dropPosition });
     } else if (payload.mode === 'reference_tool') {
       // Create widget directly
       const refWidget = COKER_REFERENCE_WIDGETS.find(w => w.key === payload.referenceWidgetId);
       const widget: GridWidget = {
         id: generateId(),
         referenceWidgetId: payload.referenceWidgetId,
         visualTypeId: refWidget.kind,
         parameterId: null,
         config: {},
         title: refWidget.displayName,
         layout: { ...dropPosition, w: refWidget.defaultW, h: refWidget.defaultH, minW: refWidget.minW, minH: refWidget.minH }
       };
       appendWidget(widget);
     }
   }
